  @override Widget build(BuildContext context){final lang=data['language']=='en'?'en':'es';return MaterialApp(debugShowCheckedModeBanner:false,title:'MafiFlow Mobile',theme:ThemeData(colorScheme:ColorScheme.fromSeed(seedColor:green),useMaterial3:true),darkTheme:ThemeData(colorScheme:ColorScheme.fromSeed(seedColor:green,brightness:Brightness.dark),useMaterial3:true),themeMode:dark?ThemeMode.dark:ThemeMode.light,home:!ready?const Scaffold(body:Center(child:CircularProgressIndicator())):Scaffold(appBar:AppBar(title:Row(children:[Image.asset('assets/logo.png',height:34),const SizedBox(width:10),const Text('MafiFlow Mobile')]),actions:[IconButton(icon:const Icon(Icons.settings),onPressed:()=>setState(()=>tab=5))]),body:SafeArea(child:IndexedStack(index:tab,children:[home(),transactions(),monthly(),stats(),Advisor(data:data,lang:lang,onSave:save),settings()])),bottomNavigationBar:NavigationBar(selectedIndex:tab,onDestinationSelected:(v)=>setState(()=>tab=v),labelBehavior:NavigationDestinationLabelBehavior.onlyShowSelected,destinations:[NavigationDestination(icon:const Icon(Icons.home_outlined),label:t('home')),NavigationDestination(icon:const Icon(Icons.receipt_long),label:t('moves')),NavigationDestination(icon:const Icon(Icons.event_repeat),label:t('monthly')),NavigationDestination(icon:const Icon(Icons.pie_chart_outline),label:t('stats')),NavigationDestination(icon:const Icon(Icons.smart_toy_outlined),label:t('ai')),NavigationDestination(icon:const Icon(Icons.settings_outlined),label:t('settings'))])));}
  Widget scroll(List<Widget> widgets)=>ListView(padding:const EdgeInsets.all(16),children:widgets);
  Widget stat(String label,double value,IconData icon,Color color)=>card(Row(children:[Icon(icon,color:color),const SizedBox(width:14),Expanded(child:Text(label)),Text(money(value),style:TextStyle(fontWeight:FontWeight.bold,fontSize:19,color:color))]));
  Widget home(){final v=totals();return scroll([heading(t('home')),stat(t('balance'),v.balance,Icons.account_balance_wallet,v.balance<0?expenseRed:green),stat(t('income'),v.income,Icons.trending_up,green),stat(t('expenses'),v.spent,Icons.trending_down,expenseRed),stat(t('savings'),number(data['savings_goal']),Icons.savings,Colors.blue),heading(t('recents')),...tx.reversed.take(7).map(tile)]);}
  Widget tile(Map<String,dynamic> x,{VoidCallback? onDelete}) {final plus=x['type']=='Ingreso mensual'||x['type']=='Ingreso extra';return card(ListTile(contentPadding:EdgeInsets.zero,title:Text('${x['category']??x['type']}'),subtitle:Text('${x['date']??''}\n${x['note']??''}'),isThreeLine:true,trailing:Row(mainAxisSize:MainAxisSize.min,children:[Text('${plus?'+':'−'}${money(number(x['amount']))}',style:TextStyle(color:plus?green:expenseRed,fontWeight:FontWeight.bold)),if(onDelete!=null)IconButton(onPressed:onDelete,icon:const Icon(Icons.delete_outline))])));}
  Future<void> addTransaction() async {String type='Gasto';String category='Otro';final amount=TextEditingController(),note=TextEditingController();await showDialog(context:context,builder:(c)=>StatefulBuilder(builder:(c,update)=>AlertDialog(title:Text(t('add')),content:SingleChildScrollView(child:Column(mainAxisSize:MainAxisSize.min,children:[DropdownButtonFormField<String>(value:type,items:['Gasto','Ingreso extra'].map((e)=>DropdownMenuItem(value:e,child:Text(e=='Gasto'?t('expense'):t('extra')))).toList(),onChanged:(v)=>update(()=>type=v!)),TextField(decoration:InputDecoration(labelText:t('category')),onChanged:(v)=>category=v),TextField(controller:amount,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:InputDecoration(labelText:t('amount'))),TextField(controller:note,decoration:InputDecoration(labelText:t('note')))])),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:Text(t('cancel'))),FilledButton(onPressed:(){final n=double.tryParse(amount.text.replaceAll(',','.'));if(n==null||n<=0||!n.isFinite){notice(t('invalid'));return;}data['transactions']=[...tx,{'date':stampNow(),'type':type,'category':category.trim().isEmpty?'Otro':category.trim(),'amount':n,'note':note.text}];save();Navigator.pop(c);},child:Text(t('save')))])));}
  Widget transactions()=>scroll([heading(t('moves')),FilledButton.icon(onPressed:addTransaction,icon:const Icon(Icons.add),label:Text(t('add'))),...tx.reversed.map((x)=>tile(x,onDelete:(){final list=tx;// compare values as records() creates copies
    final i=list.indexWhere((v)=>v['date']==x['date']&&v['amount']==x['amount']&&v['type']==x['type']&&v['note']==x['note']);if(i>=0)list.removeAt(i);data['transactions']=list;save();}))]);
  Future<void> addPayment()async {final name=TextEditingController(),amount=TextEditingController();await showDialog(context:context,builder:(c)=>AlertDialog(title:Text(t('newPayment')),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:name,decoration:InputDecoration(labelText:t('name'))),TextField(controller:amount,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:InputDecoration(labelText:t('amount')))]),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:Text(t('cancel'))),FilledButton(onPressed:(){final n=double.tryParse(amount.text.replaceAll(',','.'));if(n==null||n<=0||!n.isFinite||name.text.trim().isEmpty){notice(t('invalid'));return;}data['monthly_payments']=[...payments,{'name':name.text.trim(),'amount':n,'active':true}];save();Navigator.pop(c);},child:Text(t('save')))]));}
  Widget monthly()=>scroll([heading(t('monthly')),FilledButton.icon(onPressed:addPayment,icon:const Icon(Icons.add),label:Text(t('newPayment'))),...payments.asMap().entries.map((e)=>card(ListTile(title:Text('${e.value['name']}'),subtitle:Text(money(number(e.value['amount']))),leading:Switch(value:e.value['active']!=false,onChanged:(v){final list=payments;list[e.key]['active']=v;data['monthly_payments']=list;save();}),trailing:IconButton(icon:const Icon(Icons.delete_outline),onPressed:(){final list=payments;list.removeAt(e.key);data['monthly_payments']=list;save();})) ))]);
  Widget stats(){final v=totals();final income=max(0.0,v.income),spent=max(0.0,v.spent),sum=income+spent;final byCategory=<String,double>{};for(final x in tx.where((e)=>'${e['date']}'.startsWith(monthNow())&&(e['type']=='Gasto'||e['type']=='Pago mensual'))){final n=max(0.0,number(x['amount']));if(n>0)byCategory.update('${x['category']}',(old)=>old+n,ifAbsent:()=>n);}return scroll([heading(t('stats')),stat(t('income'),v.income,Icons.arrow_upward,green),stat(t('expenses'),v.spent,Icons.arrow_downward,expenseRed),card(Column(children:[Text('${t('income')} / ${t('expenses')}'),const SizedBox(height:16),SizedBox(height:200,child:sum<=0?Center(child:Text(t('noData'))):PieChart(PieChartData(sections:[if(income>0)PieChartSectionData(value:income,color:green,title:'${(100*income/sum).round()}%',radius:75),if(spent>0)PieChartSectionData(value:spent,color:expenseRed,title:'${(100*spent/sum).round()}%',radius:75)],sectionsSpace:2,centerSpaceRadius:28)))])),heading(t('category')),...byCategory.entries.map((e)=>card(Row(children:[Expanded(child:Text(e.key)),Text(money(e.value))])))]);}
  Widget settings(){final income=TextEditingController(text:'${data['monthly_income']}'),goal=TextEditingController(text:'${data['savings_goal']}'),api=TextEditingController(text:'${data['ai_api_key']}'),model=TextEditingController(text:'${data['ai_model']}'),url=TextEditingController(text:'${data['ai_base_url']}');String provider='${data['ai_provider']}';String lang='${data['language']}';String theme='${data['theme']}';return StatefulBuilder(builder:(c,update)=>scroll([heading(t('settings')),card(Column(children:[TextField(controller:income,keyboardType:TextInputType.number,decoration:InputDecoration(labelText:t('monthIncome'))),TextField(controller:goal,keyboardType:TextInputType.number,decoration:InputDecoration(labelText:t('goal'))),DropdownButtonFormField<String>(value:['OpenAI','NVIDIA','Custom'].contains(provider)?provider:'OpenAI',decoration:InputDecoration(labelText:t('provider')),items:['OpenAI','NVIDIA','Custom'].map((e)=>DropdownMenuItem(value:e,child:Text(e))).toList(),onChanged:(v)=>update(()=>provider=v!)),TextField(controller:api,obscureText:true,decoration:InputDecoration(labelText:t('key'))),TextField(controller:model,decoration:InputDecoration(labelText:t('model'))),TextField(controller:url,decoration:InputDecoration(labelText:t('custom'))),DropdownButtonFormField<String>(value:lang=='en'?'en':'es',decoration:InputDecoration(labelText:t('language')),items:const [DropdownMenuItem(value:'es',child:Text('Español')),DropdownMenuItem(value:'en',child:Text('English'))],onChanged:(v)=>update(()=>lang=v!)),DropdownButtonFormField<String>(value:theme,decoration:InputDecoration(labelText:t('theme')),items:[DropdownMenuItem(value:'light',child:Text(t('light'))),DropdownMenuItem(value:'dark',child:Text(t('dark')))],onChanged:(v)=>update(()=>theme=v!)),const SizedBox(height:12),FilledButton(onPressed:(){final inc=double.tryParse(income.text.replaceAll(',','.'));final sav=double.tryParse(goal.text.replaceAll(',','.'));if(inc==null||sav==null||!inc.isFinite||!sav.isFinite||inc<0||sav<0){notice(t('invalid'));return;}data.addAll({'monthly_income':inc,'savings_goal':sav,'ai_provider':provider,'ai_api_key':api.text.trim(),'ai_model':model.text.trim(),'ai_base_url':url.text.trim(),'language':lang,'theme':theme});save();notice(t('settingsSaved'));},child:Text(t('save')))])),card(Column(children:[ListTile(leading:const Icon(Icons.copy),title:Text(t('export')),onTap:()async{final copy=Map<String,dynamic>.from(data)..['ai_api_key']='';await Clipboard.setData(ClipboardData(text:const JsonEncoder.withIndent('  ').convert(copy)));notice(t('backup'));}),ListTile(leading:const Icon(Icons.download),title:Text(t('import')),onTap:()async{final clipboard=await Clipboard.getData('text/plain');try{final obj=jsonDecode(clipboard?.text??'');if(obj is! Map||obj['transactions'] is! List)throw const FormatException();if(!mounted)return;final ok=await showDialog<bool>(context:context,builder:(d)=>AlertDialog(title:Text(t('import')),content:Text(t('confirm')),actions:[TextButton(onPressed:()=>Navigator.pop(d,false),child:Text(t('cancel'))),FilledButton(onPressed:()=>Navigator.pop(d,true),child:Text(t('yes')))]));if(ok==true){data={...defaults,...Map<String,dynamic>.from(obj)};await save();notice(t('imported'));}}catch(_){notice(t('invalid'));}})]))]));}
